def can_make_palindrome(N, K, A):
    if N <= 1:
        return "YES"
    if K == 1:
        return "YES" if A == A[::-1] else "NO"

    odd_count = 0
    for i in range(N // 2):
        if A[i] != A[N - i - 1]:
            odd_count += 1

    if odd_count <= K:
        return "YES"
    return "NO"

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        N = int(data[index])
        K = int(data[index + 1])
        A = list(map(int, data[index + 2: index + 2 + N]))
        index += 2 + N
        results.append(can_make_palindrome(N, K, A))

    print("\n".join(results))

if __name__ == "__main__":
